codes.cmd:
/system script add name=check-internet source={
    :local pingResult [/ping 8.8.8.8 count=3];
    :local ok [:pick $pingResult 0];
    :if ($ok = "3") do={
        :log info "Internet: OK (3/3)";
    } else={
        :log warning "Internet: FAIL";
    }
}

/system script run check-internet
/log print where message~"Internet"

/system scheduler add name=hourly-report interval=1h on-event={
    /system script run check-internet;
    /ip dhcp-server lease print;
} policy=read,script,policy start-time=startup

/system scheduler print

# PPP-интерфейс для LTE-модема
/ppp profile add name=lte
/interface pppoe-client add name=lte1 interface=usb1 user=user password=pass profile=lte default-route-distance=20

# маршрут по умолчанию с большим distance — это резерв
/ip route add dst-address=0.0.0.0/0 gateway=ether1 distance=1

# переключение по факту отсутствия связи с интернетом
/tool netwatch add name=wan-check host=8.8.8.8 interval=30s timeout=3s \
    down-script={
        /ip route set [find gateway=ether1] distance=20;
        /ip route set [find gateway=10.10.10.1] distance=1;
        :log warning "Switched to LTE backup";
    } up-script={
        /ip route set [find gateway=ether1] distance=1;
        /ip route set [find gateway=10.10.10.1] distance=20;
        :log info "Primary link restored";
    }
